#include "metaCommandGroupObject.h"
#include "backend/backend_picture.h"   // ibBackendPicture::GetIconFromBase64

/* PNG */
static const wxString s_commandGroup_64_png = wxT("");

// The platform's own groups — each one picture, drawn from its SVG like every other (the Reports group is
// the report's own drawing: one act, one picture).
static const wxString s_groupImportant_64_png = wxT("");
static const wxString s_groupNormal_64_png    = wxT("");
static const wxString s_groupCreate_64_png    = wxT("");
static const wxString s_groupReports_64_png   = wxT("");
static const wxString s_groupService_64_png   = wxT("");

wxBitmap ibCommandGroupPicture(ibInterfaceCommandSection area)
{
	switch (area) {
		case ibInterfaceCommandSection_Important: return ibBackendPicture::GetBitmapFromBase64(s_groupImportant_64_png, wxSize(16, 16));
		case ibInterfaceCommandSection_Default:   return ibBackendPicture::GetBitmapFromBase64(s_groupNormal_64_png,    wxSize(16, 16));
		case ibInterfaceCommandSection_Create:    return ibBackendPicture::GetBitmapFromBase64(s_groupCreate_64_png,    wxSize(16, 16));
		case ibInterfaceCommandSection_Report:    return ibBackendPicture::GetBitmapFromBase64(s_groupReports_64_png,   wxSize(16, 16));
		case ibInterfaceCommandSection_Service:   return ibBackendPicture::GetBitmapFromBase64(s_groupService_64_png,   wxSize(16, 16));
		default:                                  return wxNullBitmap;
	}
}

wxIcon ibValueMetaObjectCommandGroup::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectCommandGroup::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_commandGroup_64_png, wxSize(16, 16));

	return icon;
}
